y -1\n-- Vitality 2\n-- HP Recovered While Healing 3\n-- MP Recovered While Healing 1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 20)\n    effect:addMod(xi.mod.DEX, -1)\n    effect:addMod(xi.mod.VIT, 2)\n    effect:addMod(xi.mod.HPHEAL, 3)\n    effect:addMod(xi.mod.MPHEAL, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/bowl_of_yayla_corbasi_+1.lua"]={["Path"]="scripts/items/bowl_of_yayla_corbasi_+1.lua",["SHA256"]="47f2043ed966d5de24655d91d307f9c324936b141ea331dfa1abc4d22b208774",["Text"]="-----------------------------------\n-- ID: 5580\n-- Item: bowl_of_yayla_corbasi_+1\n-- Food Effect: 4Hrs, All Races\n-----------------------------------\n-- HP 25\n-- Dexterity -1\n-- Vitality 3\n-- HP Recovered While Healing 5\n-- MP Recovered While Healing 2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 25)\n    effect:addMod(xi.mod.DEX, -1)\n    effect:addMod(xi.mod.VIT, 3)\n    effect:addMod(xi.mod.HPHEAL, 5)\n    effect:addMod(xi.mod.MPHEAL, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/bowl_of_yogurt.lua"]={["Path"]="scripts/items/bowl_of_yogurt.lua",["SHA256"]="589ba1c4ddd34b9a2e75bf3d351d137dbcd571f30e5a981d212d22abff3d60dc",["Text"]="-----------------------------------\n-- ID: 5575\n-- Item: Yogurt\n-- Item Effect: Restores 60 HP over 180 seconds\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local regenEffect = target:getStatusEffect(xi.effect.REGEN)\n\n    if\n        not regenEffect or\n        regenEffect:getTier() == 0\n    then\n        target:delStatusEffectSilent(xi.effect.REGEN) -- All Regen items overwrite freely, and their effect expires silently if overwritten.\n\n        target:addStatusEffect(xi.effect.REGEN, { power = 1, duration = 180, origin = user, tick = 3 })\n    else\n        action:messageID(target:getID(), xi.msg.basic.ITEM_NO_EFFECT) -- Displays no effect when attempting to overwrite tier 1, 2, 3, 4 or 5 Regen.\n\n        return 0\n    end\nend\n\nreturn itemObject\n"},["scripts/items/bowl_of_zesty_zoni.lua"]={["Path"]="scripts/items/bowl_of_zesty_zoni.lua",["SHA256"]="aade331c8f3382c309d8451b00b54b752ce8ec8bfc9e5118ecab8ce6b2ad22b7",["Text"]="-----------------------------------\n-- ID: 5619\n-- Item: Bowl of Zesti Zoni\n-- Food Effect: 4 Hrs, All Races\n-----------------------------------\n-- HP 12\n-- MP 12\n-- Strength 2\n-- Dexterity 2\n-- Vitality 2\n-- Agility 2\n-- Accuracy +2\n-- Ranged Accuracy +2\n-- Attack +2\n-- Ranged Attack +2\n-- Evasion +2\n-- MP Recovered while healing 1\n-- HP Recovered while healing 1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 12)\n    effect:addMod(xi.mod.FOOD_MP, 12)\n    effect:addMod(xi.mod.STR, 2)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.VIT, 2)\n    effect:addMod(xi.mod.AGI, 2)\n    effect:addMod(xi.mod.ACC, 2)\n    effect:addMod(xi.mod.RACC, 2)\n    effect:addMod(xi.mod.ATT, 2)\n    effect:addMod(xi.mod.RATT, 2)\n    effect:addMod(xi.mod.EVA, 2)\n    effect:addMod(xi.mod.HPHEAL, 1)\n    effect:addMod(xi.mod.MPHEAL, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/bowl_of_zoni_broth.lua"]={["Path"]="scripts/items/bowl_of_zoni_broth.lua",["SHA256"]="7175790eb3c8a723d5c9491d4d634281dc766bc80a1c640f61bad8f27f81b1e8",["Text"]="-----------------------------------\n-- ID: 5618\n-- Item: bowl_of_zoni_broth\n-- Food Effect: 3Hrs, All Races\n-----------------------------------\n-- HP 10\n-- MP 10\n-- Strength 1\n-- Dexterity 1\n-- Vitality 1\n-- Agility 1\n-- Accuracy +1\n-- Ranged Accuracy +1\n-- Attack +1\n-- Ranged Attack +1\n-- Evasion +1\n-- HP Recovered While Healing 1\n-- MP Recovered While Healing 1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 10)\n    effect:addMod(xi.mod.FOOD_MP, 10)\n    effect:addMod(xi.mod.STR, 1)\n    effect:addMod(xi.mod.DEX, 1)\n    effect:addMod(xi.mod.VIT, 1)\n    effect:addMod(xi.mod.AGI, 1)\n    effect:addMod(xi.mod.ACC, 1)\n    effect:addMod(xi.mod.RACC, 1)\n    effect:addMod(xi.mod.ATT, 1)\n    effect:addMod(xi.mod.RATT, 1)\n    effect:addMod(xi.mod.EVA, 1)\n    effect:addMod(xi.mod.HPHEAL, 1)\n    effect:addMod(xi.mod.MPHEAL, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/branch_of_gnatbane.lua"]={["Path"]="scripts/items/branch_of_gnatbane.lua",["SHA256"]="3073dddf3cc93af92c3399de2cf4c96943f7e4c12bca96b0e159fbea3bf1de41",["Text"]="-----------------------------------\n-- ID: 5984\n-- Item: Branch of Gnatbane\n-- Food Effect: 10 Mins, All Races\n-- Poison 10HP / 3Tic\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\n    if not target:hasStatusEffect(xi.effect.POISON) then\n        target:addStatusEffect(xi.effect.POISON, { power = 10, duration = 600, origin = user, tick = 3 })\n    else\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/brass_loach.lua"]={["Path"]="scripts/items/brass_loach.lua",["SHA256"]="1b3cf59b722edff96bef148e9fba291f75da86763fdeecef4e27a8bebd47a99e",["Text"]="-----------------------------------\n-- ID: 5469\n-- Item: Brass Loach\n-- Food Effect: 5 Min, Mithra only\n-----------------------------------\n-- Dexterity +2\n-- Mind +4\n-- Evasion +5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.MND, 4)\n    effect:addMod(xi.mod.EVA, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/breath_mantle.lua"]={["Path"]="scripts/items/breath_mantle.lua",["SHA256"]="603b98e3116ec982ec275ccf9e6c2cc885ae7ba968581f7bdb37287efd824651",["Text"]="-----------------------------------\n-- ID: 15486\n-- Item: Breath Mantle\n-- Item Effect: HP+18 / Enmity+3\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.BREATH_MANTLE) ~= nil then\n        target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.BREATH_MANTLE)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.BREATH_MANTLE) then\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 1800, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.BREATH_MANTLE })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.HP, 18)\n    effect:addMod(xi.mod.ENMITY, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/bretzel.lua"]={["Path"]="scripts/items/bretzel.lua",["SHA256"]="154d5f1f982bd1997499afbcfdfc3527a25e94234ea47c9699f39f653a3beab8",["Text"]="-----------------------------------\n-- ID: 4391\n-- Item: Bretzel\n-- Food Effect: 3Min, All Races\n-----------------------------------\n-- Magic % 8\n-- Magic Cap 55\n-- Vitality 2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 180, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MPP, 8)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 55)\n    effect:addMod(xi.mod.VIT, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/brilliant_snow.lua"]={["Path"]="scripts/items/brilliant_snow.lua",["SHA256"]="bb4431ed2124d83b8d8165749eafcf8a1cb7ad9bca0154cdfc4331b5db0e3438",["Text"]="-----------------------------------\n-- ID: 4216\n-- Item: Briliant Snow\n-- Creates a spiral of \"snow\" effects\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\nend\n\nreturn itemObject\n"},["scripts/items/broach_lance.lua"]={["Path"]="scripts/items/broach_lance.lua",["SHA256"]="13265fc70dbda9a45c902617f2e7e9561f497856f58122c5107ffa9b00464760",["Text"]="-----------------------------------\n-- ID: 18122\n-- Item: Broach Lance\n-- Item Effect: TP +10\n-- Duration: Instant\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:addTP(100)\nend\n\nreturn itemObject\n"},["scripts/items/broiled_carp.lua"]={["Path"]="scripts/items/broiled_carp.lua",["SHA256"]="85fb1dd26f2c89a5e95c7539a65deb0043a71b8a9b836b536a62202f56e54fab",["Text"]="-----------------------------------\n-- ID: 4586\n-- Item: Broiled Carp\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Dexterity 2\n-- Mind -1\n-- Ranged ATT % 14 (cap 45)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.MND, -1)\n    effect:addMod(xi.mod.FOOD_RATTP, 14)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 45)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/broiled_eel.lua"]={["Path"]="scripts/items/broiled_eel.lua",["SHA256"]="2c15335c02dfc6327924114e42982faf3387508f2b7dd394de309ee7a292da66",["Text"]="-----------------------------------\n-- ID: 4588\n-- Item: Broiled Eel\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Dexterity 4\n-- Mind -3\n-- Evasion 5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 4)\n    effect:addMod(xi.mod.MND, -3)\n    effect:addMod(xi.mod.EVA, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/broiled_pipira.lua"]={["Path"]="scripts/items/broiled_pipira.lua",["SHA256"]="d1d591f7247a524cfda315ffad3a5d5080b0750a62d2be76606d63f390985bcf",["Text"]="-----------------------------------\n-- ID: 4585\n-- Item: Broiled Pipira\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Dexterity 4\n-- Mind -1\n-- Attack % 14 (cap 80)\n-- Ranged ATT % 14 (cap 80)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 4)\n    effect:addMod(xi.mod.MND, -1)\n    effect:addMod(xi.mod.FOOD_ATTP, 14)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 80)\n    effect:addMod(xi.mod.FOOD_RATTP, 14)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 80)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/broiled_trout.lua"]={["Path"]="scripts/items/broiled_trout.lua",["SHA256"]="f8677ebec263082c79b59c7a35ef358efffcbd03bd33f97c091a2ad012866abf",["Text"]="-----------------------------------\n-- ID: 4587\n-- Item: Broiled Trout\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Dexterity 4\n-- Mind -1\n-- Ranged ATT % 14 (cap 55)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 4)\n    effect:addMod(xi.mod.MND, -1)\n    effect:addMod(xi.mod.FOOD_RATTP, 14)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 45)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/bronze_bandolier.lua"]={["Path"]="scripts/items/bronze_bandolier.lua",["SHA256"]="be86bbbd54dcdf53f94feaede5338966183a9941168f7e6bf823d451a3348028",["Text"]="-----------------------------------\n-- ID: 15926\n-- Bronze Bandolier\n-- When used, you will obtain one stack of Bronze Bullets\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.BRONZE_BULLET, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/bronze_bed.lua"]={["Path"]="scripts/items/bronze_bed.lua",["SHA256"]="da866f8cbc6506e1d3195a915994df9639686c8a0e0b461ee4f70037c6fe6fd7",["Text"]="-----------------------------------\n-- ID: 5\n-- Item: Bronze Bed\n-----------------------------------\n---@type TItemFurniture\nlocal itemObject = {}\n\nitemObject.onFurniturePlaced = function(player)\n    if player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.GIVE_A_MOOGLE_A_BREAK) == xi.questStatus.QUEST_AVAILABLE then\n        xi.quest.setVar(player, xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.GIVE_A_MOOGLE_A_BREAK, 'bedPlacedTime', GetSystemTime())\n        xi.quest.setLocalVar(player, xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.GIVE_A_MOOGLE_A_BREAK, 'mustZone', 1)\n    end\nend\n\nitemObject.onFurnitureRemoved = function(player)\n    xi.quest.setVar(player, xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.GIVE_A_MOOGLE_A_BREAK, 'bedPlacedTime', 0)\nend\n\nreturn itemObject\n"},["scripts/items/bronze_bolt_quiver.lua"]={["Path"]="scripts/items/bronze_bolt_quiver.lua",["SHA256"]="a15f5c46feb32c66033f57b596a90f8ebe7e98a1c6bc81d42f20e8ba1f94d34a",["Text"]="-----------------------------------\n-- ID: 4227\n-- Item: Bronze Bolt Quiver\n-- When used, you will obtain one stack of Bronze Bolts\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.BRONZE_BOLT, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/bronze_bullet_pouch.lua"]={["Path"]="scripts/items/bronze_bullet_pouch.lua",["SHA256"]="321f6be16dc2ac4b73626f9848346ce40f189088ed929820b262ebd875b6d401",["Text"]="-----------------------------------\n-- ID: 5359\n-- Item: Bronze Bullet Pouch\n-- When used, you will obtain one stack of Bronze Bullets\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.BRONZE_BULLET, 99 } })\nend\n\nreturn itemObject\n"}};
